    port=freeport()
    with proxy('nginx','nginx.conf',dict(PORT=port,A=a,B=b)):
        for host,prefix in [('api.example.test','A'),('API.EXAMPLE.TEST:'+str(port),'A'),('assets.example.test','B'),('ASSETS.EXAMPLE.TEST:'+str(port),'B')]:
