import contextlib,http.server,http.client,socket,subprocess,threading,time,pathlib,os,re
ROOT=pathlib.Path.cwd()
def freeport():
    with socket.socket() as s:s.bind(('127.0.0.1',0));return s.getsockname()[1]
@contextlib.contextmanager
def origin(label):
    counts={}
    class Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            counts[self.path]=counts.get(self.path,0)+1
            body=(label+':'+self.path+':'+str(counts[self.path])).encode()
            self.send_response(200)
            self.send_header('Content-Length',str(len(body)))
            if self.path.startswith('/private'):self.send_header('Cache-Control','private')
            elif self.path.startswith('/nostore'):self.send_header('Cache-Control','no-store')
            else:self.send_header('Cache-Control','public, max-age=30')
            self.end_headers();self.wfile.write(body)
        def log_message(self,*args):pass
    server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler)
    thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
    try:yield server.server_port,counts
    finally:server.shutdown();server.server_close();thread.join(2);assert not thread.is_alive()
def request(port,path='/',host='example.test',address='127.0.0.1'):
    c=http.client.HTTPConnection(address,port,timeout=2)
    try:
        c.request('GET',path,headers={'Host':host});r=c.getresponse();return r.status,r.read(),dict(r.getheaders())
    finally:c.close()
@contextlib.contextmanager
def proxy(tool,source,values):
    text=pathlib.Path(source).read_text()
    for key,value in values.items():text=text.replace('@'+key+'@',str(value))
    text=text.replace('@ROOT@',str(ROOT))
    assert '@' not in text,'unresolved fixture placeholder'
    if tool=='nginx':
        assert re.search(r'\bdaemon\s+off\s*;',text) and re.search(r'\bworker_processes\s+1\s*;',text)
        for endpoint in re.findall(r'\blisten\s+([^;\s]+)',text):
            assert endpoint in ['127.0.0.1:'+str(values['PORT']),'[::1]:'+str(values['PORT'])],endpoint
        for directive in ['pid','error_log','client_body_temp_path','proxy_temp_path','fastcgi_temp_path','uwsgi_temp_path','scgi_temp_path']:
            match=re.search(r'\b'+directive+r'\s+([^;\s]+)',text)
            assert match and pathlib.Path(match[1]).is_relative_to(ROOT),directive+' must use task directory'
    else:
        assert re.search(r'^\s*nbthread\s+1\s*$',text,re.M)
        assert re.search(r'^\s*maxconn\s+32\s*$',text,re.M)
        for key in ['connect','client','server']:assert re.search(r'^\s*timeout\s+'+key+r'\s+\d+(?:ms|s)\s*$',text,re.M)
        assert re.findall(r'^\s*bind\s+(\S+)',text,re.M)==['127.0.0.1:'+str(values['PORT'])]
    config=ROOT/('rendered-'+source);config.write_text(text)
    if tool=='nginx':
        command=['nginx','-p',str(ROOT)+'/', '-c',str(config)]
        syntax=subprocess.run(command+['-t'],capture_output=True,text=True,timeout=3)
        assert syntax.returncode==0,syntax.stderr
    else:
        command=['haproxy','-f',str(config),'-db']
        subprocess.run(['haproxy','-c','-f',str(config)],check=True,capture_output=True,timeout=3)
    log=open(ROOT/(tool+'.log'),'wb');p=subprocess.Popen(command,stdout=log,stderr=log)
    try:
        for _ in range(100):
            assert p.poll() is None,'proxy exited: '+(ROOT/(tool+'.log')).read_text(errors='replace')
            try:
                with socket.create_connection(('127.0.0.1',values['PORT']),timeout=.1):break
            except OSError:time.sleep(.02)
        else:raise AssertionError('proxy did not listen')
        yield
    finally:
        if p.poll() is None:p.terminate()
        try:p.wait(timeout=3)
        except subprocess.TimeoutExpired:p.kill();p.wait(timeout=2)
        log.close()


